class Monitor:
    def __init__(self):
        self.alert=False
    @staticmethod
    def risky(d):
        return d <= 35
m=Monitor()
print(Monitor.risky(34))
print(m.risky(45))
print(m.alert)

class Monitor:
    def __init__(self,alert=False):
        self.alert=alert
    @classmethod
    def off(cls):
        return cls(False)
m=Monitor.off()
print(type(m).__name__,m.alert)

class Monitor:
    def __init__(self):
        self.alert=False
    def step(self,d):
        if not self.alert and d<=35:
            self.alert=True
        elif self.alert and d>=41:
            self.alert=False
        return self.alert
m=Monitor()
for distance in [45,34,38,42]:
    print(m.step(distance))

from dataclasses import dataclass
@dataclass
class Decision:
    status: str
    valid: bool

def check(x)->Decision:
    return Decision('ACTIVE',x>0)
result=check(34)
print(result.status,result.valid)
